 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    split = h // 2

    def rail_side(r0, r1):
        left = sum(g[r][0] != bg for r in range(r0, r1))
        right = sum(g[r][w - 1] != bg for r in range(r0, r1))
        return 0 if left >= right else w - 1

    upper_side = rail_side(0, split)
    lower_side = rail_side(split, h)
    for r in range(split, h):
        for c in range(1, w - 1):
            color = g[r][c]
            if color != bg:
                # The marker is the endpoint; extend its color to the rail.
                if lower_side == 0:
                    for x in range(1, c):
                        g[r][x] = color
                else:
                    for x in range(c + 1, w - 1):
                        g[r][x] = color
                g[r][c] = 4
                # The matching row in the opposite half is filled from its rail
                # across the open span.
                rr = r - split
                if upper_side == 0:
                    for x in range(1, w):
                        g[rr][x] = color
                else:
                    for x in range(0, w - 1):
                        g[rr][x] = color
                break
    return g

if __name__ == '__main__':
    test = [[9] + [6] * 22 for _ in range(20)]
    for r in range(10, 16): test[r][-1] = 9
    test[14][6] = 8
    out = transform(test)
    assert out[4] == [9] + [8] * 22
